package com.horology.store.shared.data

import androidx.room.ConstructedBy
import androidx.room.Database
import androidx.room.RoomDatabase
import androidx.room.RoomDatabaseConstructor

@Database(
    entities = [CartItemEntity::class, FavoriteEntity::class],
    version = 1,
    exportSchema = true,
)
@ConstructedBy(HorologyDatabaseConstructor::class)
abstract class HorologyDatabase : RoomDatabase() {
    abstract fun cartDao(): CartDao
    abstract fun favoriteDao(): FavoriteDao
}

/** Actuals generated by Room's KSP compiler on every platform (KMP contract). */
@Suppress("NO_ACTUAL_FOR_EXPECT")
expect object HorologyDatabaseConstructor : RoomDatabaseConstructor<HorologyDatabase>
